function srch(q){q=q.trim().toLowerCase();if(!q)return [];const ids=new Set();Object.keys(SYN).forEach(k=>{if(k.startsWith(q)||q.startsWith(k))SYN[k].forEach(i=>ids.add(i))});
 PR8.forEach(p=>{const h=(p.n.join(' ')+' '+p.cat.join(' ')+' '+p.full+' '+L(ZN[p.z])).toLowerCase();if(h.includes(q))ids.add(p.id)});return [...ids].map(PB)}
