  <div class="mem">${[['AM','Amina'],['ZU',T('Zuri · 10.4 kg','Zuri · kg 10.4')],['MH',T('Mama Halima','Mama Halima')],['JU',T('Juma · guardian','Juma · mlezi')]].map(m=>`<div><div class="av">${m[0]}</div>${m[1]}</div>`).join('')}</div>
