function css8s(){if(document.getElementById('d8-csss'))return;const e=document.createElement('style');e.id='d8-csss';e.textContent=CSS8S;document.head.appendChild(e)}
// box gross profit with the model's rules: products margin on the box less packing, plus 15% on the packing-and-delivery part
const MB=(()=>{try{return MODEL.inputs.members}catch(e){return {avg_box:80500,box_products_gm:.26,packing_delivery_in_price:8500,pd_margin:0,monthly_churn:.08}}})();
const BOXGP=p=>(p-MB.packing_delivery_in_price)*((window.MODEL&&MODEL.NETF)||1)*MB.box_products_gm+MB.packing_delivery_in_price*(MB.pd_margin||0);
const RET=(p,del)=>p*NETF8*RGM+(del?(ON.delivery_fee-ON.rider_cost_per_order):0);
const BEATS=[
 {d:1,ch:'store',img:'hero',t:['Day 1 · The first visit','Siku 1 · Ziara ya kwanza'],p:['Amina comes into the Mbezi store for a thermometer. The quick check at the door (blood pressure, pulse and oxygen, about 50 seconds) shows her blood pressure slightly raised at 128/82. She takes the free Afya Green card at the counter, and staff set up the app on her phone in two minutes.','Amina anaingia duka la Mbezi kununua kipimajoto. Kipimo cha haraka mlangoni (shinikizo la damu, mapigo ya moyo na oksijeni, takriban sekunde 50) kinaonyesha shinikizo lake liko juu kidogo, 128/82. Anachukua kadi ya bure ya Afya Green kaunta, na wafanyakazi wanaweka programu kwenye simu yake ndani ya dakika mbili.'],tw:['The Twin record opens: one household, one reading, one purchase.','Kumbukumbu ya Twin inafunguliwa: kaya moja, kipimo kimoja, ununuzi mmoja.'],sp:PB(66).p,gp:RET(PB(66).p)},
 {d:3,ch:'app',img:'e-mama',t:['Day 3 · The family joins','Siku 3 · Familia inajiunga'],p:['At home she adds baby Zuri (10.4 kg), her mother Mama Halima in Sinza, and her brother Juma in London as a guardian who may pay for and see his mother’s care.','Nyumbani anamwongeza mtoto Zuri (kg 10.4), mama yake Mama Halima aliyeko Sinza, na kaka yake Juma aliyeko London kama mlezi anayeweza kulipia na kuona huduma ya mama yao.'],tw:['Now it knows three people, their stages and who may see what.','Sasa inajua watu watatu, hatua zao na nani anaweza kuona nini.'],sp:0,gp:0},
 {d:7,ch:'wa',img:'night',t:['Day 7 · 23:10, a fever','Siku 7 · Saa 5:10 usiku, homa'],p:['Zuri wakes up hot. Amina messages the WhatsApp number; a pharmacist answers, and children’s paracetamol syrup is ordered and delivered at 08:00 the next morning.','Zuri anaamka na joto. Amina anatuma ujumbe WhatsApp; mfamasia anajibu, na dawa ya maji ya paracetamol ya watoto inaagizwa na kuletwa saa 2:00 asubuhi.'],tw:['It notes the illness so a reminder for a temperature recheck goes out.','Inarekodi ugonjwa ili ukumbusho wa kupima joto tena utumwe.'],sp:9000+ON.delivery_fee,gp:RET(9000,1)},
 {d:10,ch:'card',img:'abroad',t:['Day 10 · From London','Siku 10 · Kutoka London'],p:['Juma, his sister and his cousin form a Care Circle for Mama Halima’s Presha Care box. Their three payments cover it in one evening; the box is packed the next morning.','Juma, dada yake na binamu yake wanaunda Mduara wa Afya kwa box la Presha Care la Mama Halima. Malipo yao matatu yanalikamilisha jioni moja; box linafungwa asubuhi inayofuata.'],tw:['A second household linked to the first, paid from abroad.','Kaya ya pili imeunganishwa na ya kwanza, imelipwa kutoka nje.'],sp:35000,gp:BOXGP(35000)},
 {d:12,ch:'sms',img:'feature',t:['Day 12 · A basic phone','Siku 12 · Simu ya kawaida'],p:['Mama Halima has a keypad phone. She receives one SMS: her box arrives tomorrow, the code is 7714. She also gets a reminder to measure her blood pressure.','Mama Halima ana simu ya vitufe. Anapokea SMS moja: box lake linafika kesho, namba ni 7714. Pia anapata ukumbusho wa kupima shinikizo la damu.'],tw:['Same platform, no smartphone needed.','Jukwaa lile lile, bila simu janja.'],sp:0,gp:0},
 {d:14,ch:'app',img:'pack',t:['Day 14 · The Mama na Mtoto box','Siku 14 · Box la Mama na Mtoto'],p:['Amina’s own monthly box ships. Two days before it locks, the Twin suggested moving Zuri from size 3 to size 4 nappies; she accepted with one tap and the price did not change.','Box la Amina la kila mwezi linatumwa. Siku mbili kabla ya kufungwa, Twin ilipendekeza kumhamisha Zuri kutoka nepi saizi 3 hadi 4; alikubali kwa kubonyeza mara moja na bei haikubadilika.'],tw:['It predicted the size change from weight and purchases.','Ilitabiri mabadiliko ya saizi kutoka uzito na manunuzi.'],sp:390000,gp:BOXGP(390000)},
 {d:21,ch:'app',img:'door',t:['Day 21 · Before it runs out','Siku 21 · Kabla hakijaisha'],p:['Extra nappies and wipes bought in the store are running low. The refill radar prepares the basket three days early; Amina confirms by voice in Kiswahili and it arrives that afternoon.','Nepi na wipes za ziada zilizonunuliwa dukani zinakaribia kuisha. Rada ya kujaza inaandaa kikapu siku tatu kabla; Amina anathibitisha kwa sauti kwa Kiswahili na kinafika mchana huo.'],tw:['It learns this family’s real use rate.','Inajifunza kasi halisi ya matumizi ya familia hii.'],sp:PB(36).p+PB(39).p+ON.delivery_fee,gp:RET(PB(36).p+PB(39).p,1)},
 {d:28,ch:'store',img:'e-heart',t:['Day 28 · The recheck','Siku 28 · Kupima tena'],p:['Amina returns for the full Afya Check, 15 measurements in about 4 minutes. Her blood pressure is 126/80, slightly better. The result appears in the app beside her earlier readings, and she shares it with Juma. She leaves with a pill organiser for her mother.','Amina anarudi kwa Afya Check kamili, vipimo 15 ndani ya takriban dakika 4. Shinikizo lake ni 126/80, nafuu kidogo. Majibu yanaonekana kwenye programu pamoja na vipimo vyake vya awali, na anayashiriki na Juma. Anaondoka na kisanduku cha kupangia vidonge kwa ajili ya mama yake.'],tw:['A health trend, not just a sales history.','Mwenendo wa afya, si historia ya mauzo tu.'],sp:PB(379).p,gp:RET(PB(379).p)}];
