function storyHTML(){return `<div class="tl" id="d8tl"><div class="fill" id="d8tlf"></div>${BEATS.map((b,i)=>`<button type="button" data-b="${i}"><i></i><span>${T('DAY','SIKU')} ${b.d}</span></button>`).join('')}</div>
 <div class="st8"><div id="d8btc"></div><div><div class="eyb">${T('Running ledger','Daftari linaloendelea')}</div><div class="led" id="d8led" style="margin-top:12px"></div><div style="display:flex;gap:10px;margin-top:20px;flex-wrap:wrap"><button class="bt sm" type="button" id="d8sty" style="background:#141614;border-color:#141614;color:#fff">▶ ${T('Play the month','Cheza mwezi')}</button><button class="bt o sm" type="button" id="d8stn" style="color:#141614;border-color:#cfc9bd">${T('Next day','Siku inayofuata')} →</button></div>
 <p style="font-size:.84rem;color:var(--ink3);margin-top:16px">${T(`Prices are catalogue prices (section 3.6) and Afya Box 1-month prices (section 3.5). Gross profit follows the master model: ${Math.round(RGM*100)}% on products net of VAT, ${TS(ON.delivery_fee-ON.rider_cost_per_order)} margin per delivery, and the Afya Box rules. Names are illustrative.`,`Bei ni za katalogi (sehemu 3.6) na bei za Afya Box za mpango wa mwezi 1 (sehemu 3.5). Faida ghafi inafuata mpango mkuu: ${Math.round(RGM*100)}% kwa bidhaa bila VAT, ${TS(ON.delivery_fee-ON.rider_cost_per_order)} kwa kila usafirishaji, na kanuni za Afya Box. Majina ni ya mfano.`)}</p></div></div>`}
function storyPaint(){const i=STY.i,b=BEATS[i];document.querySelectorAll('#d8tl button').forEach((x,j)=>{x.classList.toggle('on',j===i);x.classList.toggle('done',j<i)});document.getElementById('d8tlf').style.width=(i/(BEATS.length-1)*100)+'%';
 document.getElementById('d8btc').innerHTML=`<div class="bt8" style="animation:d8in .45s ease"><div class="im" style="background-image:url(img/d8/${b.img}.webp)"><span>${L(CHN[b.ch])}</span></div><div class="tx"><small>${L(b.t).split(' · ')[0]}</small><h3>${L(b.t).split(' · ')[1]}</h3><p>${L(b.p)}</p><div class="tw"><b>${T('What the Twin learns','Twin inajifunza nini')}:</b> ${L(b.tw)}</div></div></div>`;
 const upto=BEATS.slice(0,i+1),sp=upto.reduce((t,x)=>t+x.sp,0),gp=upto.reduce((t,x)=>t+x.gp,0),used=new Set(upto.map(x=>x.ch));
 document.getElementById('d8led').innerHTML=`<div><span>${T('Family spent so far','Familia imetumia hadi sasa')}</span><b>${TS(sp)}</b></div><div><span>${T('Afya Basics gross profit','Faida ghafi ya Afya Basics')}</span><b>${TS(gp)}</b></div><div><span>${T('People in the Twin','Watu kwenye Twin')}</span><b>${i>=1?4:1}</b></div><div><span>${T('Doors used','Milango iliyotumika')}</span><div class="ch8">${Object.keys(CHN).map(k=>`<u class="${used.has(k)?'on':''}">${L(CHN[k])}</u>`).join('')}</div></div>`}
function initStory(){const tl=document.getElementById('d8tl');if(!tl)return;storyPaint();tl.onclick=e=>{const b=e.target.closest('[data-b]');if(!b)return;stopSty();STY.i=+b.dataset.b;storyPaint()};
 document.getElementById('d8stn').onclick=()=>{stopSty();STY.i=(STY.i+1)%BEATS.length;storyPaint()};
 document.getElementById('d8sty').onclick=()=>{if(styT){stopSty();return}STY.i=0;storyPaint();document.getElementById('d8sty').textContent='❚❚ '+T('Pause','Simamisha');styT=setInterval(()=>{if(!document.getElementById('d8tl')){stopSty();return}if(STY.i>=BEATS.length-1){stopSty();return}STY.i++;storyPaint()},4200)}}
function stopSty(){clearInterval(styT);styT=null;const b=document.getElementById('d8sty');if(b)b.textContent='▶ '+T('Play the month','Cheza mwezi')}
/* money */
function moneyHTML(){const gpo=RET(ON.basket,1),bgp=BOXGP(MB.avg_box);const F=(()=>{try{return MODEL.inputs.memberships||MODEL.inputs.plans}catch(e){return null}})();
 const E5=[[T('Engine 1','Injini 1'),TS(ON.basket*NETF8*RGM),T('Product margin per online order','Faida ya bidhaa kwa oda ya mtandaoni'),T(`${Math.round(RGM*100)}% gross margin on a ${TS(ON.basket)} basket net of VAT, the same margin as the shelf.`,`Faida ghafi ya ${Math.round(RGM*100)}% kwa kikapu cha ${TS(ON.basket)} bila VAT, sawa na rafu.`)],
 [T('Engine 2','Injini 2'),TS(ON.delivery_fee-ON.rider_cost_per_order),T('Delivery margin per order','Faida ya usafirishaji kwa oda'),T(`The customer pays ${TS(ON.delivery_fee)}; the rider costs ${TS(ON.rider_cost_per_order)}. Each delivery covers its own cost.`,`Mteja analipa ${TS(ON.delivery_fee)}; msafirishaji anagharimu ${TS(ON.rider_cost_per_order)}. Kila usafirishaji unajilipia.`)],
 [T('Engine 3','Injini 3'),TS(bgp),T('Afya Box gross profit per member a month','Faida ghafi ya Afya Box kwa mwanachama kwa mwezi'),T(`Average box ${TS(MB.avg_box)}: ${Math.round(MB.box_products_gm*100)}% on products net of VAT; the box and delivery are charged at cost.`,`Wastani wa box ${TS(MB.avg_box)}: ${Math.round(MB.box_products_gm*100)}% kwa bidhaa bila VAT; box na usafirishaji vinatozwa kwa bei ya gharama.`)],
 [T('Engine 4','Injini 4'),'TSh 20–30k',T('Membership fee a year','Ada ya uanachama kwa mwaka'),T('Afya Family TSh 20,000, Afya Senior TSh 25,000, Afya Care TSh 30,000; Afya Green is free (section 3.4).','Afya Family TSh 20,000, Afya Senior TSh 25,000, Afya Care TSh 30,000; Afya Green ni bure (sehemu 3.4).')],
 [T('Engine 5','Injini 5'),T('Less waste','Upotevu mdogo'),T('Stock bought to the Twin forecast','Stoo inayonunuliwa kwa utabiri wa Twin'),T('Knowing next week’s demand means less cash tied up in shelves and fewer expired packs.','Kujua mahitaji ya wiki ijayo kunamaanisha pesa kidogo zimekwama rafuni na pakiti chache zinazoisha muda.')]];
 const LAD=[[T('One walk-in basket','Kikapu kimoja cha dukani'),T(`TSh 25,000 at ${Math.round(RGM*100)}%, net of VAT`,`TSh 25,000 kwa ${Math.round(RGM*100)}%, bila VAT`),25000*NETF8*RGM,''],[T('One online order','Oda moja ya mtandaoni'),T('TSh 35,000 + delivery','TSh 35,000 + usafirishaji'),gpo,''],[T('One Afya Box member, one month','Mwanachama mmoja wa Afya Box, mwezi mmoja'),T(`Average box ${TS(MB.avg_box)}`,`Wastani wa box ${TS(MB.avg_box)}`),bgp,'m'],[T('Box member who also reorders once a month','Mwanachama anayeagiza tena mara moja kwa mwezi'),T('The Twin’s target household','Kaya lengwa ya Twin'),bgp+gpo,'m']];const mx=Math.max(...LAD.map(x=>x[2]));
 return `<div class="eng">${E5.map(e=>`<div class="gl rv"><small>${e[0]}</small><b>${e[1]}</b><h4>${e[2]}</h4><p>${e[3]}</p></div>`).join('')}</div>
 <h3 class="rv" style="font:400 1.7rem var(--serif);margin:60px 0 0">${T('The value ladder: what one household earns us','Ngazi ya thamani: kaya moja inatuingizia nini')}</h3><p class="rv" style="color:var(--ink2);margin:8px 0 0;max-width:70ch">${T('Gross profit per customer type, from the master model. The app is designed to move customers up each step; the top step is the household the Afya Twin is built to create.','Faida ghafi kwa kila aina ya mteja, kutoka mpango mkuu. Programu imeundwa kuwapandisha wateja kila hatua; hatua ya juu ni kaya ambayo Afya Twin imejengwa kuiunda.')}</p>
 <div class="lad" id="d8lad">${LAD.map(l=>`<div class="rv"><div><b>${l[0]}</b><span>${l[1]}</span></div><div class="tr"><i class="${l[3]}" data-w="${(l[2]/mx*100).toFixed(1)}"></i></div><em>${TS(l[2])}</em></div>`).join('')}</div>
 <div class="ltv gl rv"><div><div class="eyb">${T('Retention drives member value','Kuwabakiza wanachama ndiko kunakoleta thamani')}</div><p style="margin:12px 0 0;color:var(--ink2)">${T(`The master model assumes ${Math.round(MB.monthly_churn*100)}% of members leave each month, so an average member stays about ${(1/MB.monthly_churn).toFixed(1)} months. Published subscription benchmarks range from 8% to 15%. The slider shows the value of keeping families longer through the Twin, Care Circles and reminders, and the cost if churn is higher.`,`Mpango mkuu unachukulia ${Math.round(MB.monthly_churn*100)}% ya wanachama wanaondoka kila mwezi, hivyo mwanachama wa wastani anakaa takriban miezi ${(1/MB.monthly_churn).toFixed(1)}. Viwango vilivyochapishwa vya biashara za usajili ni kati ya 8% na 15%. Kitelezi kinaonyesha thamani ya kuzibakiza familia muda mrefu zaidi kupitia Twin, Mduara wa Afya na ukumbusho, na hasara iwapo wanaoondoka ni wengi zaidi.`)}</p>
 <div class="sl" style="margin-top:18px;border-top:1px solid var(--line2)"><label>${T('Members leaving each month','Wanachama wanaoondoka kila mwezi')}<b id="d8ch1">${(MB.monthly_churn*100).toFixed(1)}%</b></label><input type="range" id="d8ch" min="3" max="15" step="0.5" value="${MB.monthly_churn*100}"></div></div>
 <div id="d8ltv"></div></div>`}
function ltvOut(c){const life=1/(c/100),v=life*BOXGP(MB.avg_box),base=1/MB.monthly_churn*BOXGP(MB.avg_box);return `<div class="eyb">${T('Gross profit over a member’s life','Faida ghafi katika maisha ya mwanachama')}</div><div class="big8" style="margin-top:12px">${TS(v)}</div><p style="color:var(--ink2);margin:12px 0 0">${T('Average stay','Wastani wa kukaa')} <b style="color:var(--ink)">${life.toFixed(0)} ${T('months','miezi')}</b> · ${v>=base?`<b style="color:#7fd6c2">+${TS(v-base)}</b> ${T('versus the model','ukilinganisha na mpango')}`:`<b style="color:#f0a37f">−${TS(base-v)}</b> ${T('versus the model','ukilinganisha na mpango')}`}</p><p style="font-size:.84rem;color:var(--ink3);margin:10px 0 0">${T(`Scenario only: the plan stays at ${Math.round(MB.monthly_churn*100)}%. The actual rate will be reported monthly once members exist.`,`Hali ya mfano tu: mpango unabaki ${Math.round(MB.monthly_churn*100)}%. Kiwango halisi kitaripotiwa kila mwezi wanachama wakianza.`)}</p>`}
function initMoney(){const s=document.getElementById('d8ch');if(!s)return;const o=document.getElementById('d8ltv'),l=document.getElementById('d8ch1');const f=()=>{l.textContent=(+s.value).toFixed(1)+'%';o.innerHTML=ltvOut(+s.value)};s.oninput=f;f();
 const lad=document.getElementById('d8lad');const io=new IntersectionObserver(es=>{if(es[0].isIntersecting){lad.querySelectorAll('i[data-w]').forEach(i=>i.style.width=i.dataset.w+'%');io.disconnect()}},{threshold:.3});io.observe(lad)}
