function compHTML(){const C=[T('Neighbourhood pharmacy','Duka la dawa la mtaani'),T('Supermarket','Supamaketi'),T('Online pharmacy apps','Programu za famasia mtandaoni'),T('Social-media sellers','Wauzaji wa mitandao ya kijamii')];
 const R=[[T('Health, baby, senior and devices in one place','Afya, mtoto, wazee na vifaa mahali pamoja'),'h','h','h','n'],[T('Order at night, delivered next morning','Agiza usiku, ifike asubuhi'),'n','n','y','h'],[T('Tracked delivery with a hand-over code','Usafirishaji unaofuatiliwa na namba ya makabidhiano'),'n','n','h','n'],[T('Pay by mobile money in one prompt','Lipa kwa pesa ya simu kwa ombi moja'),'h','h','y','h'],[T('Batch and expiry visible to the customer','Bechi na tarehe ya mwisho zinaonekana kwa mteja'),'n','n','n','n'],[T('Health checks linked to what you buy','Vipimo vya afya vinavyounganishwa na unachonunua'),'n','n','n','n'],[T('Refills predicted before they run out','Kujaza kunatabiriwa kabla ya kuisha'),'n','n','n','n'],[T('Family abroad pays and sees delivery','Familia nje inalipa na kuona usafirishaji'),'n','n','h','n'],[T('Works on a basic phone','Inafanya kazi kwenye simu ya kawaida'),'y','n','n','n'],[T('Kiswahili first, everywhere','Kiswahili kwanza, kila mahali'),'y','h','h','y']];
 return `<div class="cmp8 rv"><table><thead><tr><th>${T('What the customer gets','Mteja anapata nini')}</th>${C.map(c=>`<th>${c}</th>`).join('')}<th class="us">Afya Basics</th></tr></thead><tbody>${R.map(r=>`<tr><td>${r[0]}</td>${r.slice(1).map(v=>`<td><span class="${v}"></span></td>`).join('')}<td class="us"><span class="y"></span></td></tr>`).join('')}</tbody></table>
 <div class="lg"><span><i class="y" style="display:inline-block;width:12px;height:12px;border-radius:50%;background:#7fd6c2"></i>${T('Usually yes','Kwa kawaida ndiyo')}</span><span><i style="display:inline-block;width:12px;height:12px;border-radius:50%;background:linear-gradient(90deg,#d8b46a 50%,transparent 50%);border:1px solid #d8b46a"></i>${T('Some do','Baadhi wanafanya')}</span><span><i style="display:inline-block;width:12px;height:12px;border-radius:50%;border:1px solid rgba(236,228,210,.3)"></i>${T('Usually no','Kwa kawaida hapana')}</span></div>
 <p style="font-size:.86rem;color:var(--ink3);margin-top:12px">${T('Typical offer by category from our desk research, not a judgement of any single business; to be checked store by store in field research before launch. General e-commerce is thin: Jumia closed its Tanzania business in 2019.','Huduma ya kawaida kwa kundi kutoka utafiti wetu wa mezani, si hukumu ya biashara moja; itakaguliwa duka kwa duka katika utafiti wa uwanjani kabla ya kuzindua. Biashara ya mtandaoni kwa ujumla bado ni ndogo: Jumia ilifunga biashara yake Tanzania mwaka 2019.')} ${cn('jum')}</p></div>`}
