function wsMain(){const zs=['hd','mb','fh','pc','mr','sn'];const list=PR8.filter(p=>p.z===WS.z);const ed={hd:'e-heart',mb:'e-mama',pc:'e-glow',sn:'e-senior',fh:'e-aid',mr:'e-senior'}[WS.z];
 const title={hd:T('The Heart Edit','Mkusanyiko wa Moyo'),mb:T('The Mama Edit','Mkusanyiko wa Mama'),fh:T('The Home Care Edit','Mkusanyiko wa Nyumbani'),pc:T('The Glow Edit','Mkusanyiko wa Ngozi'),mr:T('The Recovery Edit','Mkusanyiko wa Kupona'),sn:T('The Comfort Edit','Mkusanyiko wa Starehe')}[WS.z];
 return `<header><nav>${zs.map(z=>`<button data-z="${z}" class="${WS.z===z?'on':''}">${L(ZN[z])}</button>`).join('')}</nav></header>
 <div style="display:flex;justify-content:center;padding:18px 0 14px;border-bottom:1px solid var(--line)"><img src="img/d8/logo.webp" alt="Afya Basics" style="height:34px"></div>
 <div class="bn" style="background-image:url(img/d8/${ed}.webp)"><div><small style="font:600 .66rem var(--sans);letter-spacing:.26em;text-transform:uppercase">${T('Zone','Kanda')} ${ZL[WS.z]} · ${L(ZN[WS.z])}</small><b>${title}</b><span>${T('Delivered in Dar es Salaam within hours, or ready to collect in one.','Inaletwa Dar es Salaam ndani ya saa chache, au tayari kuchukuliwa ndani ya saa moja.')}</span></div></div>
 <div class="gr">${list.map(p=>`<button data-id="${p.id}" class="${WS.sel===p.id?'on':''}"><div class="pi" style="${SP(p.id)}"></div><b>${E(L(p.n))}</b><span><em style="font-style:normal">${E(L(p.size))}</em><strong style="font-weight:600;color:var(--ink)">${TS(p.p)}</strong></span></button>`).join('')||`<p style="padding:20px;color:var(--ink3)">${T('More products in this zone in the full catalogue (section 3.6).','Bidhaa zaidi za kanda hii ziko kwenye katalogi kamili (sehemu 3.6).')}</p>`}</div>`}
function wsAside(){const p=PB(WS.sel)||PR8[0];const n=WS.bag.reduce((t,b)=>t+b.q,0),sum=WS.bag.reduce((t,b)=>t+PB(b.id).p*b.q,0);
 return `<div class="pi" style="${SP(p.id)}"></div><div>${`<span style="font:600 .62rem var(--sans);letter-spacing:.16em;text-transform:uppercase;color:var(--ink3)">${T('Zone','Kanda')} ${ZL[p.z]} · ${L(ZN[p.z])}</span>`}<h5 style="margin-top:6px">${E(L(p.n))}</h5></div>
 <p><b>${TS(p.p)}</b> · ${E(L(p.size))} · ${T('VAT included','Pamoja na VAT')}</p><p><b>${T('Best for','Inamfaa')}:</b> ${E(L(p.best))}</p>
 <button class="bt sm" data-add="${p.id}" style="background:#141614;border-color:#141614;color:#fff;justify-content:center">${T('Add to bag','Weka kwenye begi')}</button>
 <p style="font-size:.76rem;color:var(--ink3)">${T('Catalogue price from a public listing','Bei ya katalogi kutoka orodha ya wazi')} · <a href="${p.u}" target="_blank" rel="noopener" style="color:var(--g)">${T('source','chanzo')}</a></p>
 <div class="bag"><div><b>${T('Your bag','Begi lako')}</b><span>${n} ${T('items','bidhaa')}</span></div>${WS.bag.map(b=>`<div><span>${E(L(PB(b.id).n))} × ${b.q}</span><span>${TS(PB(b.id).p*b.q)}</span></div>`).join('')}<div style="border-top:1px solid var(--line);margin-top:6px;padding-top:8px"><b>${T('Total with delivery','Jumla pamoja na usafirishaji')}</b><b>${TS(sum+(n?DELF():0))}</b></div>
 <p style="font-size:.76rem;color:var(--ink3);margin-top:8px">${T('The same account, basket and prices as the app and WhatsApp.','Akaunti, kikapu na bei zile zile kama programu na WhatsApp.')}</p></div>`}
function initWeb(){const m=document.getElementById('d8wsm'),a=document.getElementById('d8wsa');if(!m)return;const draw=()=>{m.innerHTML=wsMain();a.innerHTML=wsAside()};draw();
 m.onclick=e=>{const z=e.target.closest('[data-z]'),p=e.target.closest('[data-id]');if(z){WS.z=z.dataset.z;const f=PR8.find(x=>x.z===WS.z);if(f)WS.sel=f.id;draw()}else if(p){WS.sel=+p.dataset.id;m.querySelectorAll('.gr button').forEach(b=>b.classList.toggle('on',+b.dataset.id===WS.sel));a.innerHTML=wsAside()}};
 a.onclick=e=>{const b=e.target.closest('[data-add]');if(!b)return;const id=+b.dataset.add,c=WS.bag.find(x=>x.id===id);if(c)c.q++;else WS.bag.push({id,q:1});a.innerHTML=wsAside()}}

