/* numbers: digital channel economics from the master model */
const NS={o:ON.orders_day_m12,b:ON.basket,d:100};
function numHTML(){return `<div class="nm"><div>
 <div class="sl"><label>${T('Digital orders a day','Oda za kidijitali kwa siku')}<b id="d8o1">${NS.o}</b></label><input type="range" id="d8o" min="5" max="120" step="1" value="${NS.o}"></div>
 <div class="sl"><label>${T('Average basket','Wastani wa kikapu')}<b id="d8b1">${TS(NS.b)}</b></label><input type="range" id="d8b" min="15000" max="90000" step="1000" value="${NS.b}"></div>
 <div class="sl"><label>${T('Share delivered (rest collected in store)','Sehemu inayoletwa (nyingine inachukuliwa dukani)')}<b id="d8d1">${NS.d}%</b></label><input type="range" id="d8d" min="0" max="100" step="5" value="${NS.d}"></div>
 <p class="d8nt">${T(`Defaults are the master model’s month-12 inputs for the flagship: ${ON.orders_day_m12} digital orders a day, ${TS(ON.basket)} basket, ${TS(ON.delivery_fee)} delivery fee, ${TS(ON.rider_cost_per_order)} rider cost per order and ${Math.round(RGM*100)}% product margin. Products are shown net of VAT. The model assumes every digital order is delivered.`,`Thamani za mwanzo ni za mpango mkuu kwa duka kubwa, mwezi wa 12: oda ${ON.orders_day_m12} za kidijitali kwa siku, kikapu ${TS(ON.basket)}, ada ya usafirishaji ${TS(ON.delivery_fee)}, gharama ya msafirishaji ${TS(ON.rider_cost_per_order)} kwa oda na faida ya bidhaa ${Math.round(RGM*100)}%. Bidhaa zinaonyeshwa bila VAT. Mpango unachukulia kila oda ya kidijitali inaletwa.`)}</p>
 </div><div id="d8no"></div></div>`}
function numOut(){const o=NS.o,b=NS.b,d=NS.d/100,m=30*o,fee=ON.delivery_fee,rc=ON.rider_cost_per_order;
 const rev=m*b*NETF8+m*d*fee,gp=m*b*NETF8*RGM+m*d*(fee-rc),per=gp/m,yr=rev*12;
 return `<div class="kp"><div><b>${TM(rev)}</b><span>${T('Digital revenue a month, net of VAT','Mapato ya kidijitali kwa mwezi, bila VAT')}</span></div><div><b>${TM(gp)}</b><span>${T('Gross profit a month','Faida ghafi kwa mwezi')}</span></div><div><b>${TS(per)}</b><span>${T('Gross profit per order','Faida ghafi kwa oda')}</span></div><div><b>${NF(m)}</b><span>${T('Orders a month','Oda kwa mwezi')}</span></div></div>
 <table class="t8"><thead><tr><th>${T('Line','Kipengele')}</th><th class="n">${T('Per order','Kwa oda')}</th><th class="n">${T('Per month','Kwa mwezi')}</th></tr></thead><tbody>
 <tr><td>${T('Products sold, net of VAT','Bidhaa zilizouzwa, bila VAT')}</td><td class="n">${TS(b*NETF8)}</td><td class="n">${TM(m*b*NETF8)}</td></tr>
 <tr><td>${T('Delivery fees collected','Ada za usafirishaji')}</td><td class="n">${TS(d*fee)}</td><td class="n">${TM(m*d*fee)}</td></tr>
 <tr><td>${T('Product margin at','Faida ya bidhaa kwa')} ${Math.round(RGM*100)}%</td><td class="n">${TS(b*NETF8*RGM)}</td><td class="n">${TM(m*b*NETF8*RGM)}</td></tr>
 <tr><td>${T('Delivery margin (fee less rider)','Faida ya usafirishaji (ada ukiondoa msafirishaji)')}</td><td class="n">${TS(d*(fee-rc))}</td><td class="n">${TM(m*d*(fee-rc))}</td></tr>
 <tr class="tt"><td>${T('Gross profit','Faida ghafi')}</td><td class="n">${TS(per)}</td><td class="n">${TM(gp)}</td></tr></tbody></table>
 <p class="d8nt">${T('A year at this pace','Mwaka kwa kasi hii')}: <b style="color:var(--ink)">${TM(yr)}</b> ${T('revenue. Running costs of the platform (hosting, messages, payment fees) are quoted by suppliers in the build phase and are listed in the developer blueprint below.','mapato. Gharama za kuendesha jukwaa (seva, jumbe, ada za malipo) zitanukuliwa na wasambazaji wakati wa ujenzi na zimeorodheshwa kwenye mwongozo wa msanidi hapa chini.')}</p>`}
function initNum(){const g=id=>document.getElementById(id);if(!g('d8o'))return;const out=()=>{g('d8o1').textContent=NS.o;g('d8b1').textContent=TS(NS.b);g('d8d1').textContent=NS.d+'%';g('d8no').innerHTML=numOut()};
 g('d8o').oninput=e=>{NS.o=+e.target.value;out()};g('d8b').oninput=e=>{NS.b=+e.target.value;out()};g('d8d').oninput=e=>{NS.d=+e.target.value;out()};out()}
