function bpHTML(){css8bp();return `<div class="bpt" id="d8bpt" role="tablist">${BPT.map((t,i)=>`<button role="tab" data-k="${t[0]}" class="${i?'':'on'}">${String(i+1).padStart(2,'0')} · ${L(t[1])}</button>`).join('')}</div><div class="bpb" id="d8bpb">${bpBody('map')}${bpNav(0)}</div>`}
function bpNav(i){const p=BPT[i-1],n=BPT[i+1];return `<div class="bpnav">${p?`<button class="bt o sm" type="button" data-go="${p[0]}">← ${L(p[1])}</button>`:'<span></span>'}${n?`<button class="bt sm" type="button" data-go="${n[0]}">${T('Next','Inayofuata')}: ${L(n[1])} →</button>`:''}</div>`}
function initBp(){const t=document.getElementById('d8bpt'),b=document.getElementById('d8bpb');if(!t)return;
 const prog=()=>{const p=document.getElementById('d8chp');if(p)p.style.width=(CHK.filter(Boolean).length/10*100)+'%'};
 const show=k=>{const i=BPT.findIndex(x=>x[0]===k);t.querySelectorAll('button').forEach(y=>y.classList.toggle('on',y.dataset.k===k));b.innerHTML=bpBody(k)+bpNav(i);prog();const m=document.getElementById('d8m8');if(m)m.scrollTo({top:t.getBoundingClientRect().top-m.getBoundingClientRect().top+m.scrollTop-20,behavior:'smooth'})};
 t.onclick=e=>{const x=e.target.closest('[data-k]');if(x)show(x.dataset.k)};
 b.onclick=e=>{const g=e.target.closest('[data-go]');if(g){show(g.dataset.go);return}};
 b.onchange=e=>{const c=e.target.closest('input[data-i]');if(c){CHK[+c.dataset.i]=c.checked;prog()}}}
