let heroT=null;
function bagPaint(open){const b=document.getElementById('d8bag8');if(!b)return;const sum=WB.items.reduce((t,x)=>t+x.p*x.q,0);
 b.innerHTML=`<div class="hd9"><span>${T('Your bag','Begi lako')} (${WB.n})</span><button type="button" data-x="1" aria-label="${T('Close','Funga')}">✕</button></div><div class="ls">${WB.items.length?WB.items.map(x=>`<div class="ln9"><i style="${x.id==='box'?'background:#ece7de url(img/d8/boxopen.webp) center/cover':SP(x.id)}"></i><div><b>${E(x.n)}</b><span>${T('Qty','Idadi')} ${x.q}</span></div><b>${TS(x.p*x.q)}</b></div>`).join(''):`<p style="color:#9a9a9a;margin:30px 0">${T('Your bag is empty.','Begi lako ni tupu.')}</p>`}</div>
 <div class="ft9"><div><span>${T('Subtotal','Jumla ndogo')}</span><b>${TS(sum)}</b></div><div><span>${T('Delivery today','Usafirishaji leo')}</span><b>${WB.items.length?TS(DELF()):'—'}</b></div><div style="font-weight:600;border-top:1px solid #eee;margin-top:6px;padding-top:10px"><span>${T('Total','Jumla')}</span><b>${TS(sum+(WB.items.length?DELF():0))}</b></div><button class="b1 f" type="button" data-x="1">${T('Pay with mobile money','Lipa kwa pesa ya simu')}</button></div>`;
 if(open){b.classList.add('on');document.getElementById('d8scr').classList.add('on')}}
function notePaint(k){const n=NOTES[k],p=document.getElementById('d8npan'),i=NK.indexOf(k);
 p.innerHTML=`<button class="x" type="button" data-x="1" aria-label="${T('Close','Funga')}">✕</button><small>${T('Investor note','Maelezo kwa mwekezaji')} ${i+1} / ${NK.length}</small><h4>${L(n[0])}</h4><p>${L(n[1])}</p>${n[2].length?`<div class="kv">${n[2].map(r=>`<div><span>${L(r[0])}</span><b>${r[1]}</b></div>`).join('')}</div>`:''}<div class="nv"><button class="bt o sm" type="button" data-n="${NK[(i-1+NK.length)%NK.length]}">← ${T('Previous','Iliyotangulia')}</button><button class="bt sm" type="button" data-n="${NK[(i+1)%NK.length]}">${T('Next note','Inayofuata')} →</button></div>`;
 p.classList.add('on');document.getElementById('d8scr').classList.add('on')}
function closePanels(){['d8npan','d8bag8'].forEach(id=>{const e=document.getElementById(id);if(e)e.classList.remove('on')});const s=document.getElementById('d8scr');if(s)s.classList.remove('on')}
function initSite(){const site=document.getElementById('d8site');if(!site)return;
 let k=0;const sl=[...site.querySelectorAll('.sl')],dt=[...site.querySelectorAll('#d8dots button')];const show=i=>{k=i;sl.forEach((s,j)=>s.classList.toggle('on',j===i));dt.forEach((d,j)=>{d.classList.remove('on');if(j===i){void d.offsetWidth;d.classList.add('on')}})};
 clearInterval(heroT);heroT=setInterval(()=>{if(!document.getElementById('d8site')){clearInterval(heroT);return}show((k+1)%sl.length)},6000);
 document.getElementById('d8dots').onclick=e=>{const b=e.target.closest('[data-d]');if(!b)return;clearInterval(heroT);show(+b.dataset.d)};
 const add=id=>{if(id==='box'){const i=+((document.querySelector('#d8pl .on')||{dataset:{b:0}}).dataset.b),bx=[['Afya Box · Presha Care',35000],['Afya Box · Mama na Mtoto',390000],['Afya Box · Bibi na Babu',182000]][i];const f=WB.items.find(x=>x.id==='box'&&x.n===bx[0]);if(f)f.q++;else WB.items.push({id:'box',n:bx[0],p:bx[1],q:1})}
  else{const p=PB(+id),f=WB.items.find(x=>x.id===p.id);if(f)f.q++;else WB.items.push({id:p.id,n:L(p.n),p:p.p,q:1})}
  WB.n++;const u=document.getElementById('d8bagn');u.textContent=WB.n;u.classList.add('pop');setTimeout(()=>u.classList.remove('pop'),300);bagPaint(true)};
 site.addEventListener('click',e=>{const a=e.target.closest('[data-add]'),f=e.target.closest('[data-fav]'),n=e.target.closest('[data-note]'),pb=e.target.closest('#d8pl [data-b]'),sh=e.target.closest('[data-shop]');
  if(a){add(a.dataset.add);return}if(f){const id=+f.dataset.fav;WB.fav.has(id)?WB.fav.delete(id):WB.fav.add(id);f.classList.toggle('on');return}if(n){notePaint(n.dataset.note);return}
  if(pb){document.querySelectorAll('#d8pl button').forEach(x=>x.classList.toggle('on',x===pb));return}
  if(sh){const r=document.getElementById('d8rail');if(r)r.scrollIntoView({behavior:'smooth',block:'center'});return}
  if(e.target.closest('#d8bagb')){bagPaint(true)}});
 const root=document.getElementById('d8');root.addEventListener('click',e=>{if(e.target.closest('#d8npan [data-x],#d8bag8 [data-x]')||e.target.id==='d8scr'){closePanels();return}const nn=e.target.closest('#d8npan [data-n]');if(nn)notePaint(nn.dataset.n)});
 const tog=document.getElementById('d8ntog');const sio=new IntersectionObserver(es=>tog.classList.toggle('on',es[0].isIntersecting),{threshold:0});sio.observe(site);
 tog.onclick=()=>{root.classList.toggle('nopins');tog.lastChild.textContent=root.classList.contains('nopins')?T('Investor notes: off','Maelezo ya mwekezaji: yamezimwa'):T('Investor notes: on','Maelezo ya mwekezaji: yamewashwa')};
 addEventListener('keydown',e=>{if(e.key==='Escape')closePanels()});
 addEventListener('afya:leave',()=>{clearInterval(heroT);sio.disconnect()},{once:true})}
