function lxCircle(){const R=[['Juma · London',20000],['Neema · Arusha',8500],['Amina · Dar',6500]];return {tab:'twin',html:`<div class="cc9"><div class="lbl">${T('Care Circle','Mduara wa Afya')}</div><h4>Mama Halima</h4><div class="sm">Presha Care · TSh 42,500 / ${T('month','mwezi')}</div><div class="bar"><i></i></div>${R.map((r,i)=>`<div class="r" style="animation-delay:${.4+i*.6}s"><b>${r[0]}</b><span>${TS(r[1])} ✓</span></div>`).join('')}<div class="card dk" style="opacity:0;animation:d8msg .4s ease 2.4s forwards"><div class="lbl">${T('Box covered','Box limekamilika')}</div><p style="margin:6px 0 0;font-size:.78rem">${T('Packed tomorrow, delivered 18 Nov. Everyone in the circle gets the hand-over photo.','Linafungwa kesho, linaletwa 18 Nov. Kila mtu kwenye mduara anapata picha ya makabidhiano.')}</p></div></div>`}}
