const TOUR=[{id:'d8-web',t:['The website','Tovuti'],p:['This is the store as customers will see it. Tap the gold numbered dots for investor notes, add products to the bag, and try the Afya Box selector.','Hili ndilo duka kama wateja watakavyoliona. Bonyeza vitone vya dhahabu kwa maelezo ya mwekezaji, weka bidhaa kwenye begi, na jaribu kichagua Afya Box.']},{id:'d8-sc1',t:['Afya Twin','Afya Twin'],p:['Our main invention: it restocks each family before they run out. Press “See how the Twin works” for the live simulator.','Ubunifu wetu mkuu: inaijazia kila familia kabla haijaishiwa. Bonyeza “Ona Twin inavyofanya kazi” kwa kiigizaji hai.']},{id:'d8-sc2',t:['Three more inventions','Ubunifu mingine mitatu'],p:['Afya Verified, Scan the Empty and Care Circles. Each has a “Learn more” with a working demo.','Afya Halisi, Changanua Kilichoisha na Mduara wa Afya. Kila mmoja una “Jifunze zaidi” yenye onyesho linalofanya kazi.']},{id:'d8-sc5',t:['Four doors','Milango minne'],p:['App, website, WhatsApp and SMS on one platform.','Programu, tovuti, WhatsApp na SMS kwenye jukwaa moja.']},{id:'d8-try',t:['Try it yourself','Jaribu mwenyewe'],p:['A working app prototype. Press “Play the 60-second demo” or tap anything.','Mfano wa programu unaofanya kazi. Bonyeza “Cheza onyesho la sekunde 60” au bonyeza chochote.']},{id:'d8-story',t:['One family, one month','Familia moja, mwezi mmoja'],p:['Press “Play the month” to follow 30 days with a running ledger.','Bonyeza “Cheza mwezi” kufuata siku 30 pamoja na daftari linaloendelea.']},{id:'d8-sc9',t:['The numbers','Takwimu'],p:['Member value and digital revenue from the master model. “See how it makes money” opens the full breakdown.','Thamani ya mwanachama na mapato ya kidijitali kutoka mpango mkuu. “Ona inavyoingiza pesa” inafungua uchambuzi kamili.']},{id:'d8-sc11',t:['For developers','Kwa wasanidi'],p:['The full blueprint and the risks open from here.','Mwongozo kamili na hatari vinafunguliwa kutoka hapa.']}];
let d8io=null;
function init(){const root=document.getElementById('d8');if(!root)return;initLaunchX();initSite();initScenes();initQ();initApp();initStory();document.getElementById('d8tour').onclick=()=>tour(TOUR);
 root.addEventListener('click',e=>{const a=e.target.closest('[data-jump]');if(!a)return;e.preventDefault();const t=document.getElementById(a.dataset.jump);if(t)scrollTo({top:t.getBoundingClientRect().top+scrollY,behavior:'smooth'})});
 if(d8io)d8io.disconnect();const rv=root.querySelectorAll('.rv');
 if('IntersectionObserver' in window){d8io=new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting){en.target.classList.add('in');d8io.unobserve(en.target)}}),{rootMargin:'0px 0px -8% 0px'});rv.forEach(x=>d8io.observe(x))}else rv.forEach(x=>x.classList.add('in'));
 addEventListener('afya:leave',()=>{stopAuto(true);stopSty();waT.forEach(clearTimeout);clearInterval(trkT);closePanels()},{once:true})}
window.SECTIONS['s3-8']={render,init};
